+		{"2026-01-15T10:00:00+02:00", false},
+		{"not-a-date", true},
+		{"", true},
+	}
+	for _, tt := range tests {
+		t.Run(tt.input, func(t *testing.T) {
+			t.Parallel()
+			_, err := parseFlexibleTime(tt.input)
